('ddeb936f-6883-4a2d-b73b-24204bd4a010', '10000', '270af1db-4fd8-43f2-a0e4-dcb823232b95', 'bd354104-e32b-4b11-b22e-6b42e8b53440', '# Summary
该文档为国网重庆市电力公司出具的一份电费账单，账单对象为重庆星达铜业有限公司（户号5001654065328），用电类别为大工业用电，电压等级为交流10千伏，供电服务单位为璧城供电服务中心，用电地址位于重庆市璧山区青杠街道莲花社区。账单周期为2026年7月1日至7月31日，账单打印日期为2026年8月5日，交费截止日期为2026年8月9日。

核心数据方面，本期总电量为655,058千瓦时，环比增长1.42%；本期电费合计471,420.85元，平均电价0.71966元/千瓦时。该户为市场化零售客户，采用工商业两部制分时电价，电能表倍率为3000。

费用构成主要包括：工商业电费469,266.76元，其中市场化购电费266,658.01元（零售交易电费281,323.34元按0.436元/千瓦时的统一电价计收，同时包含中长期偏差回收返还-19,369.56元、零售交易发电侧收益返还-5,086.34元、零售损益分摊电费10,432.2元等调整项目）；上网环节线损费用11,816.23元；输配电费123,416.88元（含按2000千伏安、22元/千伏安计收的容量电费44,000元）；系统运行费36,601.71元（含煤电容量电费14,565.58元、燃气机组容量电费9,532.09元等）；政府性基金及附加30,773.93元。此外，居民定比电量9,821千瓦时对应居民电费5,205.13元；功率因数调整电费为-3,051.04元，因实际功率因数0.97高于0.90的标准而获得下调。

用能分析显示，本期尖峰、峰、平、谷分时电量分别为11,193、108,790、200,408、324,846千瓦时，占比为1.71%、16.61%、32.09%、49.59%，低谷时段用电占比过半。账单备注还说明了工商业用户分时时段划分（尖峰12:00-14:00、低谷00:00-08:00等）以及两部制用户选择容量或需量计费的申请规则。', '9', 't', '0', '0', '', '', 'summary', '851f7b4e-a832-4a9d-8b55-478576a9b343', '', NULL, NULL, '2026-09-10 03:56:02.99262+00', '2026-09-10 03:56:02.99262+00', NULL, NULL, '', '0', '', '1', '100001112', NULL, '# Summary
