('81a1bcc4-b25e-494e-89ef-4dccc415cda3', '10000', 'f0f32eb9-69d8-4cec-8ec3-d2e6014a06b3', '7f2d39ad-1afd-4eb8-b807-34e192f8ca6d', '# Summary
本制度旨在加强货运车辆安全管理，规范货运车辆运营行为，提高运输效率，保障人民群众生命财产安全。制度适用于本单位所有货运车辆及其驾驶员，要求安装符合国家标准的GPS车载终端，并与监管平台联网。监控人员负责实时监控车辆运行状态，包括超速、偏离路线、进入禁行区域等异常情况，并定期分析数据，评估车辆运行状况。驾驶员违反规定将受到批评教育、经济处罚等处理。制度还包含了GPS车载终端的安装规范和监管平台操作手册。', '10', 't', '0', '0', '', '', 'summary', '0521f230-7bbb-4687-b864-4b8439d58158', '', NULL, NULL, '2026-09-07 09:53:41.632826+00', '2026-09-07 09:53:41.632826+00', NULL, NULL, '', '0', '', '1', '100000817', NULL, '# Summary
