('75f0a3fc-8a03-461a-a1fd-5ca9e43c1761', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '5d202df7-aaa5-4505-bdb0-fad2fe97b2be', '这是一份协议文件的第三页，主要内容为“四、其他约定”部分，包括：双方自愿签订协议、签订后不得反悔、协议自签字盖章之日起生效（一式二份），以及违约方需支付违约金人民币10万元并承担相关费用等条款。页面下方为签署栏：甲方盖有“重庆星达铜业有限公司”红色公章，乙方有签字及红色手印，双方签署日期均为2026年4月24日。', '0', 't', '0', '0', '', '', 'image_caption', 'c0f26544-0003-45ab-8798-068b1f3d1606', '[{"url":"resource://WPCC8x7CQoh80Zalqsjcnw","original_url":"resource://WPCC8x7CQoh80Zalqsjcnw","start_pos":0,"end_pos":0,"caption":"这是一份协议文件的第三页，主要内容为“四、其他约定”部分，包括：双方自愿签订协议、签订后不得反悔、协议自签字盖章之日起生效（一式二份），以及违约方需支付违约金人民币10万元并承担相关费用等条款。页面下方为签署栏：甲方盖有“重庆星达铜业有限公司”红色公章，乙方有签字及红色手印，双方签署日期均为2026年4月24日。","ocr_text":"4. 双方互不追究其他责任，无任何未结争议、纠纷及未了事项。\n\n## 四、其他约定\n\n1. 甲、乙双方在自愿的基础上签订本协议，系甲、乙双方真实意思表示，不存在任何欺诈与胁迫，甲、乙双方均确信已充分理解本协议中的所有条款。\n\n2. 本协议签订后，双方再无其他争议，任何一方不得反悔。\n\n3. 本协议自甲乙双方签字、盖章之日起生效。本协议一式二份，甲乙双方各持一份。\n\n4. 本协议签订后，任何一方违反本协议规定，属于违约，违约方需向守约方支付违约金人民币 100000 元。因任何一方违约而导致诉讼、仲裁或申请强制执行的，应当向对方支付实现债权的费用，包括但不限于律师费、诉讼费、保全费等。\n\n甲方盖章：（盖章：重庆星达铜业有限公司）\n\n乙方（签字按手印）：刘乐仪（手写签名，并按手印）\n\n日期：2026 年 4 月 24 日（手写）　　　　日期：2026 年 4 月 24 日（手写）"}]', NULL, NULL, '2026-09-07 00:56:17.71681+00', '2026-09-07 00:56:19.686464+00', '2026-09-07 06:09:29.210095+00', NULL, '', '2', '', '1', '100000488', NULL, '这是一份协议文件的第三页，主要内容为“四、其他约定”部分，包括：双方自愿签订协议、签订后不得反悔、协议自签字盖章之日起生效（一式二份），以及违约方需支付违约金人民币10万元并承担相关费用等条款。页面下方为签署栏：甲方盖有“重庆星达铜业有限公司”红色公章，乙方有签字及红色手印，双方签署日期均为2026年4月24日。', '0', 'ready', '', ''),
