('3b184639-baa2-4b45-889f-9ef36ec7ed82', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '7007ce3b-3dec-48fd-a930-ba191e10a92e', '这是一份检测服务合同的第3页（共4页）。内容包括：
- “其他”条款部分：列举了关于检测报告有效期、CMA章效力、报告复制规定、补充协议、争议解决（如协商不成向重庆市渝北区人民法院起诉）等事项。
- 落款签署区：甲方为重庆星达铜业有限公司（盖红色合同专用章），乙方为重庆大安检测技术有限公司（盖灰色合同专用章），双方填写了地址、电话、开户银行、账号、税号等信息，签署日期均为2026年4月24日。', '0', 't', '0', '0', '', '', 'image_caption', 'd3ed95cd-7ea4-4fe4-a278-dbe356060b03', '[{"url":"resource://dqPObpgyy1GDrppQKFMgfg","original_url":"resource://dqPObpgyy1GDrppQKFMgfg","start_pos":0,"end_pos":0,"caption":"这是一份检测服务合同的第3页（共4页）。内容包括：\n- “其他”条款部分：列举了关于检测报告有效期、CMA章效力、报告复制规定、补充协议、争议解决（如协商不成向重庆市渝北区人民法院起诉）等事项。\n- 落款签署区：甲方为重庆星达铜业有限公司（盖红色合同专用章），乙方为重庆大安检测技术有限公司（盖灰色合同专用章），双方填写了地址、电话、开户银行、账号、税号等信息，签署日期均为2026年4月24日。","ocr_text":"| 条款 | 内容 |\n|------|------|\n| （续） | 7. 甲方单方原因更改乙方出具的检测报告，或对乙方出具的检测报告进行取舍，由此造成损失或纠纷时；\u003cbr\u003e8. 甲方由于其提供的样品、技术文件存在知识产权问题，由此造成损失或纠纷时。 |\n| 其他 | 1.乙方不作检测数据必达标的承诺，若检测数据不达标，则需甲方整改后复测；并需签订补充协议，报告时限顺延。\u003cbr\u003e2.乙方的报告如未加盖 CMA 章和检验检测专用章无效，涂改无效，复印无效。未经乙方同意，不得复制报告。经同意复制的报告必须全文复制，如未重新加盖乙方检验检测专用章，则该复制件无效。\u003cbr\u003e3.未加盖 CMA 章的检测报告仅供甲方内部使用，不具有向社会出示公正性的作用。\u003cbr\u003e4.在协议执行过程中，本协议附件与本协议具有同等效力。\u003cbr\u003e5.如有未尽事宜，经双方协商可签订补充协议，补充协议与本协议具有同等法律效力。\u003cbr\u003e6.本协议一式贰份，经双方签字盖章后生效，甲、乙双方各持壹份；扫描件、复印件具有同等法律效力。\u003cbr\u003e7.在履行本合同过程中发生争议时，双方应尽友好协商解决；如协商未能解决，则直接向重庆市渝北区人民法院起诉。 |\n\n| 甲方 | 乙方 |\n|------|------|\n| 甲方：重庆星达铜业有限公司 | 乙方：重庆大安检测技术有限公司 |\n| 委托代理人：（签名） | 委托代理人：（签名） |\n| 地址：（手写，部分字迹不清）……路106号 | 地址：重庆市渝北区食品城大道18号重庆广告产业园12-1-6-1、12-1-6-2 |\n| 电话：13996910075（手写） | 电话：17830549433 |\n| 开户银行： | 开户银行：中国民生银行股份有限公司重庆两江新区支行 |\n| 账户： | 账号：699955589（部分被印章遮挡） |\n| 税号： | 税号：91500112MA5UMBWK03 |\n| 日期：2026年4月24日（手写） | 日期：2026年4月24日（手写） |"}]', NULL, NULL, '2026-09-07 00:57:22.082017+00', '2026-09-07 00:57:23.389084+00', NULL, NULL, '', '2', '', '1', '100000496', NULL, '这是一份检测服务合同的第3页（共4页）。内容包括：
- “其他”条款部分：列举了关于检测报告有效期、CMA章效力、报告复制规定、补充协议、争议解决（如协商不成向重庆市渝北区人民法院起诉）等事项。
- 落款签署区：甲方为重庆星达铜业有限公司（盖红色合同专用章），乙方为重庆大安检测技术有限公司（盖灰色合同专用章），双方填写了地址、电话、开户银行、账号、税号等信息，签署日期均为2026年4月24日。', '0', 'ready', '', ''),
