关于员工介绍福利及值班补贴调整的通知 
公司各部门、各子公司：
根据公司管理制度，为提高员工福利，故对以下事项进行
调整：
一、 推荐员工入职福利调整： 
员工介绍新员工入职满 3 个月，介绍人领取 600 元奖励，入
职满 1 年，介绍人再领取 1200 元奖励。
二、各类休假期间，值班补贴标准调整： 
1、法定节假日值班按 90 元/天（停产安保人员值班按 240 元
/天、增加值班人员按 300 元/天）补贴标准计发。
2、法定节假日相邻休息日值班按 50 元/天（停产安保人员值
班按 200 元/天、增加值班人员按 240 元/天）补贴标准计发。
 
 
 成都星达铜业有限公司
