| | 4.采样平台必须保证安全、牢固，否则乙方不予采样，且一切发生费用由甲方负责。<br>5.按本协议约定及时向乙方支付检测费用。<br>6.检测报告未经乙方同意不得擅自修改，不得提供或转让给第三方使用。 |
| 乙方责任和义务 | 1.按照合同约定提供检测服务，为甲方出具检测报告。<br>2.采用合适谨慎态度及科学准确的方法，以保证提供优质、高效、准确、快速的检测服务。<br>3.乙方应采用国家规定的检验方法和标准，在双方协商一致的时间内完成分析测试任务并出具检测报告给甲方。<br>4.乙方必须对一切检测数据和检验结果保密，除法律规定外，未经甲方书面同意不得泄露给任何第三方。<br>5.乙方出具的检测报告，仅对被送检样品和现场采取的样品负责。在任何情况下，乙方的责任不能超出乙方对样品作出的检测报告的范围。检测结果的使用、使用所产生的直接或间接损失，乙方不承担任何责任。<br>6.承诺现场采样人员在采样过程中严禁以任何形式索取好处费或其他与客户约定之外的行为，保证廉洁检测。 |
| 保密条款 | 1.甲方应为乙方所提供的技术情报和资料及非正式出版物等承担保密义务。<br>2.乙方应为甲方所提供的资料、环境状况、产品技术、生产工艺等承担保密义务。<br>3.未经对方书面许可，任何一方不得向第三方泄露本合同的如下内容：合作范围、内容、方式、费用；双方权利、责任；争议处理的方式等等。<br>4.一旦一方泄密，则泄密方必须承担相应的经济和法律责任。 |
| 违约责任 | 1.因甲方原因（受检单位监测条件不能达到要求）导致乙方检测人员到达现场后无法进行采样或不能一次性完成的（即超出天数），乙方不承担责任；且甲方需额外向乙方支付人工及车辆费用（人工费用按每人每天500元计算，不足1天按1天计；车辆费用按每车每公里2元计算）；<br>2.现场检测人员仅对本协议委托项目进行采样。如遇现场实际情况与协议不符或需更改协议，需另外以书面方式写明更改要求，并由甲方代表人签字或单位盖章，检测工作完成时间自甲方盖章生效之日起重新计算；<br>3.甲方若因付款不及时或未按照要求付款，导致报告延期的，所产生的一切责任和后果甲方自己承担，与乙方无关；<br>4.若不是乙方原因而甲方未能按本合同约定付款，甲方应按下列比例向乙方支付滞纳金：每迟一日，甲方向乙方支付该笔延付款的0.1%违约金，付款日期以甲方银行承付日期为准，迟付款违约金总金额不超过合同总金额的20%；<br>5.甲乙双方若无正当理由要求解除协议的，违约方应当向守约方支付协议总价的20%作为违约金；<br>6.若此项目需要复测，要收取复测费用，复测费用双方协商，并签订补充协议；<br>7.一方违反保密条款导致协议另一方遭受损失或不利影响的，应按协议总价款的10%支付违约金。 |
| 免责条款 | 检测服务的顺利进行，依靠甲乙双方的共同努力和彼此配合。因在乙方控制范围之外的原因造成乙方无法履行合同条款时，乙方不承担相关责任，情况包括但不限于以下：<br>1. 发生不可抗力时，任何一方对于由以下不可抗力造成的违约均不负有法律责任：政府的法律法规；<br>2. 自然灾害，包括但不限于洪水、旱灾、台风、地震、火灾、疫情等；<br>3. 罢工或暴乱；<br>4. 战争或军事行为或国际制裁；<br>5. 甲方人员不按照本合同条款履行责任时，如资料或样品不能按照乙方要求提供时；<br>6. 由于甲方原因致使乙方未能按合同规定完成检测服务而造成甲方蒙受任何损失或损害时； |', '0', 't', '0', '0', '', '', 'image_ocr', 'd3ed95cd-7ea4-4fe4-a278-dbe356060b03', '[{"url":"resource://oxK6FvBuH0Edph2nsSryUg","original_url":"resource://oxK6FvBuH0Edph2nsSryUg","start_pos":0,"end_pos":0,"caption":"这是一份检测服务合同的第二页（共4页），以表格形式列出了以下主要内容：\n\n- **乙方责任和义务**：乙方须按规定提供检测服务、出具检测报告，对检测数据保密，并对样品检测结果负责，保证廉洁检测。\n- **保密条款**：甲乙双方须对彼此提供的技术资料、合作协议内容等保密，泄密方承担相应经济和法律责任。\n- **违约责任**：包括因甲方原因无法采样时乙方的免责及费用承担（人工每天500元、车辆每公里2元）、付款逾期违约金（每日0.1%，上限为合同总额20%）、单方解约须支付20%违约金、泄密赔偿10%等规定。\n- **免责条款**：列明不可抗力、自然灾害、罢工骚乱、战争、甲方不履行合同义务等情况下乙方可免除责任。\n\n页面右侧盖有部分红色印章，显示与中国银行（大同）相关的印记。","ocr_text":"| | |\n|---|---|\n| | 4.采样平台必须保证安全、牢固，否则乙方不予采样，且一切发生费用由甲方负责。\u003cbr\u003e5.按本协议约定及时向乙方支付检测费用。\u003cbr\u003e6.检测报告未经乙方同意不得擅自修改，不得提供或转让给第三方使用。 |\n| 乙方责任和义务 | 1.按照合同约定提供检测服务，为甲方出具检测报告。\u003cbr\u003e2.采用合适谨慎态度及科学准确的方法，以保证提供优质、高效、准确、快速的检测服务。\u003cbr\u003e3.乙方应采用国家规定的检验方法和标准，在双方协商一致的时间内完成分析测试任务并出具检测报告给甲方。\u003cbr\u003e4.乙方必须对一切检测数据和检验结果保密，除法律规定外，未经甲方书面同意不得泄露给任何第三方。\u003cbr\u003e5.乙方出具的检测报告，仅对被送检样品和现场采取的样品负责。在任何情况下，乙方的责任不能超出乙方对样品作出的检测报告的范围。检测结果的使用、使用所产生的直接或间接损失，乙方不承担任何责任。\u003cbr\u003e6.承诺现场采样人员在采样过程中严禁以任何形式索取好处费或其他与客户约定之外的行为，保证廉洁检测。 |\n| 保密条款 | 1.甲方应为乙方所提供的技术情报和资料及非正式出版物等承担保密义务。\u003cbr\u003e2.乙方应为甲方所提供的资料、环境状况、产品技术、生产工艺等承担保密义务。\u003cbr\u003e3.未经对方书面许可，任何一方不得向第三方泄露本合同的如下内容：合作范围、内容、方式、费用；双方权利、责任；争议处理的方式等等。\u003cbr\u003e4.一旦一方泄密，则泄密方必须承担相应的经济和法律责任。 |\n| 违约责任 | 1.因甲方原因（受检单位监测条件不能达到要求）导致乙方检测人员到达现场后无法进行采样或不能一次性完成的（即超出天数），乙方不承担责任；且甲方需额外向乙方支付人工及车辆费用（人工费用按每人每天500元计算，不足1天按1天计；车辆费用按每车每公里2元计算）；\u003cbr\u003e2.现场检测人员仅对本协议委托项目进行采样。如遇现场实际情况与协议不符或需更改协议，需另外以书面方式写明更改要求，并由甲方代表人签字或单位盖章，检测工作完成时间自甲方盖章生效之日起重新计算；\u003cbr\u003e3.甲方若因付款不及时或未按照要求付款，导致报告延期的，所产生的一切责任和后果甲方自己承担，与乙方无关；\u003cbr\u003e4.若不是乙方原因而甲方未能按本合同约定付款，甲方应按下列比例向乙方支付滞纳金：每迟一日，甲方