('e81b3dd8-15d9-4471-8eab-edffba314233', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '7ca2cee1-f5b7-4c17-8587-21f21a0e1645', '这份图片是一份公租房租赁合同的第3页（共10页）。主要内容为：甲方将位于璧山区的两山景苑公租房共10套（其中集体宿舍10套），建筑面积合计485.55平方米，出租给乙方使用。租赁期限为2年，自2025年5月1日至2027年4月30日止。租金按建筑面积计算，标准为6元/平方米/月，月租金共计2915元；物业管理费为每月486元。合同还约定租赁期满需续租的，应提前3个月提出书面申请。页面右侧可见部分红色印章。', '0', 't', '0', '0', '', '', 'image_caption', '7200c5e7-ebb0-48bb-9943-2da2ab9beece', '[{"url":"resource://I_FmWbfUn8FQTsWr_Oc18g","original_url":"resource://I_FmWbfUn8FQTsWr_Oc18g","start_pos":0,"end_pos":0,"caption":"这份图片是一份公租房租赁合同的第3页（共10页）。主要内容为：甲方将位于璧山区的两山景苑公租房共10套（其中集体宿舍10套），建筑面积合计485.55平方米，出租给乙方使用。租赁期限为2年，自2025年5月1日至2027年4月30日止。租金按建筑面积计算，标准为6元/平方米/月，月租金共计2915元；物业管理费为每月486元。合同还约定租赁期满需续租的，应提前3个月提出书面申请。页面右侧可见部分红色印章。","ocr_text":"甲方将璧山区　　　两山景苑公租房　　　（以下简称房屋），共计　10　套（其中集体宿舍　10　套，员工自住　0　套）建筑面积共计 485.55 平方米（以权威机构出具的房屋建筑面积测算报告书为准），出租给乙方，供其符合居住公租房条件职工居住使用或作为集体宿舍使用。此处房屋为钢混结构，户型为：一室一厅(10套)　　　，房屋信息见附件及设施设备见交接清单，该附件作为甲方按照本合同约定交付乙方使用和乙方在本合同租赁期满交还该房屋时的验收依据。\n\n**第二条　租赁期限**\n\n该房屋租赁期限为　2　年，　租期自　2025　年　05　月　01　日至　2027　年　04　月　30　日止。\n\n租赁期满，乙方应如期交还该房屋。如需继续租住，应在租赁期满3个月前向甲方提出书面续租申请。经审查符合条件的，双方重新签订租赁合同。\n\n**第三条　租金标准及物业管理费标准**\n\n一、该房屋按建筑面积计算租金，租金标准为　6　元/平方米/月，共计月租金为人民币　　　　　2915　　　　元（大写：　　　　贰仟玖佰壹拾伍圆整　　　　　　元整）。\n\n二、物业管理费按该房屋按建筑面积计算，标准为　　　　　　元/平方米/月，共计月租金为人民币　　486　　元（大写：肆佰捌拾陆圆整　　　　　）。\n\n租赁期内，按照《璧山高新技术产业开发区公共租赁住房管理实施细则》的相关规定调整租金和物业费标准的，乙方承诺按照调整后的标准缴纳租金及物业费。"}]', NULL, NULL, '2026-09-07 01:02:52.528203+00', '2026-09-07 01:02:54.010604+00', '2026-09-07 07:25:10.850614+00', NULL, '', '2', '', '1', '100000521', NULL, '这份图片是一份公租房租赁合同的第3页（共10页）。主要内容为：甲方将位于璧山区的两山景苑公租房共10套（其中集体宿舍10套），建筑面积合计485.55平方米，出租给乙方使用。租赁期限为2年，自2025年5月1日至2027年4月30日止。租金按建筑面积计算，标准为6元/平方米/月，月租金共计2915元；物业管理费为每月486元。合同还约定租赁期满需续租的，应提前3个月提出书面申请。页面右侧可见部分红色印章。', '0', 'ready', '', ''),
