('44b95dc9-307f-4e43-a4bd-ac4ac02962be', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '5d202df7-aaa5-4505-bdb0-fad2fe97b2be', '这是一份劳动合同解除/终止结算协议的第2页，主要内容包括：

**结算款项部分：**
1. **工资结算**：甲方支付乙方工资至2026年3月11日，共计人民币1117元；
2. **经济补偿金**：甲方支付乙方经济补偿金共计19500元；
3. **其他费用**：社保缴至2026年4月（其中4月社保费1902.76元自理）；
4. **付款安排**：甲方于2026年4月24日前一次性支付17597.24元至乙方指定账户（户名刘正伦，开户行为中国建设银行重庆璧山支行）。

**权利义务与无争议声明部分：**
- 乙方确认协议为双方真实意思表示，不存在欺诈、胁迫等情形；
- 甲方付清全部款项后，双方基于劳动关系的权利义务终结；
- 乙方承诺收款后不再就工资、社保、工伤等事宜以任何形式向甲方主张权利，否则视为违约。

