重庆星达铜业有限公司与昆明吉庆祥食品有限责任公司签订了一份销售订购合同。合同内容包括甲方订购乙方的一批月饼，合同总额为11,441.70元，包含13%的发票和运输费用。交货地址在重庆市璧山区青杠街道新立路106号，交货日期为9月8日。甲方提供产品组合包装，乙方通过单位名称为昆明吉庆祥食品有限责任公司的账户进行对公转账支付。合同中还承诺提供的产品符合国家规定标准，并符合国家食品卫生法和产品质量法的相关规定。合同一式两份，双方签字盖章后生效。', '2', 't', '0', '0', '', '', 'summary', '80235f8d-6466-4884-a361-f32f59690216', '', NULL, NULL, '2026-09-04 07:37:08.347168+00', '2026-09-04 07:37:08.347168+00', '2026-09-04 07:37:13.462509+00', NULL, '', '0', '', '1', '100000437', NULL, '# Summary
