('f3218330-7601-4ed4-8730-34e74e8dc5ed', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '7ca2cee1-f5b7-4c17-8587-21f21a0e1645', '这是一份公共租赁住房租赁合同的第9页（共10页）。内容包括第十二条“其他约定事项”，规定了乙方（承租方）拖欠租金将记入信用档案、需按时缴纳水电物业等费用、每年向高新区管委会申报产值税收等情况，以及损坏赔偿责任、物业公司代管、换租申请等条款。文末载明甲方指定账户为重庆两山建设投资集团有限公司在重庆银行璧山支行的账户，并盖有红色公章。', '0', 't', '0', '0', '', '', 'image_caption', 'ba969090-8875-4609-ba31-6b12aa74cc5c', '[{"url":"resource://FoG4SM8Kif5n7W8ongv1bg","original_url":"resource://FoG4SM8Kif5n7W8ongv1bg","start_pos":0,"end_pos":0,"caption":"这是一份公共租赁住房租赁合同的第9页（共10页）。内容包括第十二条“其他约定事项”，规定了乙方（承租方）拖欠租金将记入信用档案、需按时缴纳水电物业等费用、每年向高新区管委会申报产值税收等情况，以及损坏赔偿责任、物业公司代管、换租申请等条款。文末载明甲方指定账户为重庆两山建设投资集团有限公司在重庆银行璧山支行的账户，并盖有红色公章。","ocr_text":"（六）甲方知晓乙方违约的事实而又接受租金、押金或其他费用时，并不表示甲方放弃追究乙方违约责任的权利。乙方缴付租金或其他款项如有不足额的情况，甲方接受该不足额的款项并不表示甲方同意减免，也不影响其追索不足部分的租金或欠款的权利以及按本合同和法律规定采取其他措施的权利。\n\n**第十二条 其他约定事项**\n\n（一）乙方拖欠租金和其他费用的，将有关情况记入乙方信用档案。合同解除或终止时，可从其履约保证金中直接划扣。\n\n（二）乙方应按时交纳房屋使用过程中发生的水、电、气、通讯、有线电视、物业服务等相关费用。\n\n（三）乙方应当每年向高新区管委会申报产值、税收、职工人数等情况，未按规定申报的，视为放弃租赁住房，合同终止。\n\n（四）乙方行为致甲方物业公共区域或第三人损害的，由乙承担全部损害赔偿责任。\n\n（五）甲方委托物业公司对该房屋进行管理，代为履行甲方在本合同项下的权利和义务。\n\n（六）出售管理按市、区公共租赁住房出售管理相关政策执行。\n\n（七）因工作地点发生变化需变更房屋地点的，可向高新区管委会提出换租申请，经审核、公示符合条件的重新参加配租，换租完成后，重新签订租赁合同，并按规定腾退原承租的住房。\n\n（八）甲方指定账户：\n\n重庆两山建设投资集团有限公司：\n\n重庆银行璧山支行：　　　　　　650102029001548782"}]', NULL, NULL, '2026-09-07 01:02:47.03775+00', '2026-09-07 01:02:48.694141+00', '2026-09-07 07:25:10.850614+00', NULL, '', '2', '', '1', '100000511', NULL, '这是一份公共租赁住房租赁合同的第9页（共10页）。内容包括第十二条“其他约定事项”，规定了乙方（承租方）拖欠租金将记入信用档案、需按时缴纳水电物业等费用、每年向高新区管委会申报产值税收等情况，以及损坏赔偿责任、物业公司代管、换租申请等条款。文末载明甲方指定账户为重庆两山建设投资集团有限公司在重庆银行璧山支行的账户，并盖有红色公章。', '0', 'ready', '', ''),
('0d9439ac-2a62-4de6-a506-e927ff00d61a', '10000', 'f0f32eb9-69d8-4cec-8ec3-d2e6014a06b3', 'aede5c3b-55a2-4e66-9139-1417fc9a375e', '# Summary
成都星达铜业有限公司发布了一则关于员工福利及值班补贴调整的通知。主要内容包括：

1. 推荐员工入职福利调整：员工介绍新员工入职满3个月，介绍人可领取600元奖励；入职满1年，介绍人再领取1200元奖励。

2. 各类休假期间值班补贴标准调整：法定节假日值班补贴为90元/天，停产安保人员值班为240元/天，增加值班人员为300元/天；法定节假日相邻休息日值班补贴为50元/天，停产安保人员值班为200元/天，增加值班人员为240元/天。

通知由成都星达铜业有限公司人事行政部于2021年10月19日印发。', '2', 't', '0', '0', '', '', 'summary', '2941e44c-28f0-4190-a516-8e6f67652720', '', NULL, NULL, '2026-09-07 09:56:15.114816+00', '2026-09-07 09:56:15.114816+00', '2026-09-07 09:56:54.619829+00', NULL, '', '0', '', '1', '100000821', NULL, '# Summary
