2. 各类休假期间值班补贴标准调整：法定节假日值班补贴为90元/天，停产安保人员值班为240元/天，增加值班人员为300元/天；法定节假日相邻休息日值班补贴为50元/天，停产安保人员值班为200元/天，增加值班人员为240元/天。

