('0c225007-06ee-465b-83f9-b50fb4acdc5a', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '7ca2cee1-f5b7-4c17-8587-21f21a0e1645', '甲方将璧山区　　　两山景苑公租房　　　（以下简称房屋），共计　10　套（其中集体宿舍　10　套，员工自住　0　套）建筑面积共计 485.55 平方米（以权威机构出具的房屋建筑面积测算报告书为准），出租给乙方，供其符合居住公租房条件职工居住使用或作为集体宿舍使用。此处房屋为钢混结构，户型为：一室一厅(10套)　　　，房屋信息见附件及设施设备见交接清单，该附件作为甲方按照本合同约定交付乙方使用和乙方在本合同租赁期满交还该房屋时的验收依据。

**第二条　租赁期限**

该房屋租赁期限为　2　年，　租期自　2025　年　05　月　01　日至　2027　年　04　月　30　日止。

租赁期满，乙方应如期交还该房屋。如需继续租住，应在租赁期满3个月前向甲方提出书面续租申请。经审查符合条件的，双方重新签订租赁合同。

**第三条　租金标准及物业管理费标准**

一、该房屋按建筑面积计算租金，租金标准为　6　元/平方米/月，共计月租金为人民币　　　　　2915　　　　元（大写：　　　　贰仟玖佰壹拾伍圆整　　　　　　元整）。

二、物业管理费按该房屋按建筑面积计算，标准为　　　　　　元/平方米/月，共计月租金为人民币　　486　　元（大写：肆佰捌拾陆圆整　　　　　）。

