本期总电量为555,617千瓦时，环比下降15.18%；尖峰、峰、平、谷分时电量分别为14,177、92,683、160,816、279,611千瓦时，占比为2.55%、16.68%、30.45%、50.32%。本期电费合计393,459.72元，由工商业电费391,579.91元、居民电费4,414.90元及功率因数调整电费-2,535.09元构成。其中工商业电费包含五个部分：市场化购电费213,339.58元（含零售交易电费238,617.14元、零售损益分摊电费19,585.21元，以及中长期偏差回收返还-39,397.70元、零售交易发电侧收益返还-4,940.37元等多项返还费用）；上网环节线损费用9,453.84元；输配电费111,051元（含电量电费67,051元，以及按2000千伏安容量、22元/千伏安·月计收的容量电费44,000元）；系统运行费31,633.19元（含煤电容量电费、抽水蓄能容量电费、燃气', '9', 't', '0', '0', '', '', 'summary', '155366a1-20a3-4c3b-b7b3-e15a8b7b23e7', '', NULL, NULL, '2026-09-09 05:35:50.105821+00', '2026-09-09 05:35:50.105821+00', '2026-09-09 06:04:40.696668+00', NULL, '', '0', '', '1', '100000930', NULL, '# Summary
