('8a53e9bc-7385-4c63-b81a-ff5d3b77ea82', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '74f5976c-4849-4dfe-a213-b839dcbb90cf', '这张图片内容非常简单：画面几乎全部为空白，仅在左侧边缘可见一个部分残缺的红色圆形印章（公章），印章上有部分中文文字（隐约可见“合”等字样），其余部分为纯白色空白。', '0', 't', '0', '0', '', '', 'image_caption', '6c03e87a-5746-411f-a637-6c1b6b37a131', '[{"url":"resource://00QyLx_nmHbvaz3TAx6heA","original_url":"resource://00QyLx_nmHbvaz3TAx6heA","start_pos":0,"end_pos":0,"caption":"这张图片内容非常简单：画面几乎全部为空白，仅在左侧边缘可见一个部分残缺的红色圆形印章（公章），印章上有部分中文文字（隐约可见“合”等字样），其余部分为纯白色空白。","ocr_text":""}]', NULL, NULL, '2026-09-07 05:10:06.153585+00', '2026-09-07 05:10:07.386803+00', '2026-09-07 05:10:14.376275+00', NULL, '', '2', '', '1', '100000669', NULL, '这张图片内容非常简单：画面几乎全部为空白，仅在左侧边缘可见一个部分残缺的红色圆形印章（公章），印章上有部分中文文字（隐约可见“合”等字样），其余部分为纯白色空白。', '0', 'ready', '', ''),
('f4f5625a-988c-46cf-b5f6-0977c4b5ec60', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '7ca2cee1-f5b7-4c17-8587-21f21a0e1645', '这是一份公共租赁住房租赁合同的第6页（共10页）。主要内容为：

- **第五至七条续文**：规定乙方（承租方）需配合甲方及物业的房屋维护、入户走访、信息采集等工作；甲方设立专项维修资金用于共用部位和设施的维修改造；乙方不得在租赁房屋外墙设置标志、广告或其他凸出物。

- **第八条 合同的解除与终止**：约定甲方房屋不符合安全条件时乙方可解除合同；乙方若有骗租、转租出借、改变住房结构或使用性质等行为，甲方有权解除合同并收回房屋，且5年内不得再次申请，相关情况记入信用档案，按照《璧山高新技术产业开发区公共租赁住房管理实施细则》执行。', '0', 't', '0', '0', '', '', 'image_caption', 'f6e525c8-d7a1-454e-a781-590e3ef95d47', '[{"url":"resource://NBURZlG3_ZL51rNWRefBRg","original_url":"resource://NBURZlG3_ZL51rNWRefBRg","start_pos":0,"end_pos":0,"caption":"这是一份公共租赁住房租赁合同的第6页（共10页）。主要内容为：\n\n- **第五至七条续文**：规定乙方（承租方）需配合甲方及物业的房屋维护、入户走访、信息采集等工作；甲方设立专项维修资金用于共用部位和设施的维修改造；乙方不得在租赁房屋外墙设置标志、广告或其他凸出物。\n\n- **第八条 合同的解除与终止**：约定甲方房屋不符合安全条件时乙方可解除合同；乙方若有骗租、转租出借、改变住房结构或使用性质等行为，甲方有权解除合同并收回房屋，且5年内不得再次申请，相关情况记入信用档案，按照《璧山高新技术产业开发区公共租赁住房管理实施细则》执行。","ocr_text":"方仍未改正的，甲方有权对遗留在共用部位的物品自行处置，甲方恢复共用部位原状产生的费用由乙方承担。\n\n5、乙方应积极配合甲方或甲方委托物业管理单位以及住房保障部门的房屋维护、定期入户走访、开展日常检查，以及人脸信息采集、二维码张贴等技术手段采集租户信息登记、监督管理等工作。\n\n6、甲方建立专项维修资金用于住宅共用部位、共用设施设备保修期后的大修、更新和改造，确保共用部位和设施设备处于良好的状态。甲方如需要对房屋及附属设施进行检查或维修时，乙方应积极配合，如因乙方原因导致房屋及附属设施不能及时维修而发生安全事故的，乙方承担全部责任。\n\n7、乙方不得在租赁房屋任何部位外墙或外侧展示、树立任何标志、广告、遮蓬或其他凸出物，亦不得在租赁房屋外设置任何广告或其他设施。\n\n**第八条　合同的解除与终止**\n\n（一）甲方提供的房屋不符合安全条件的，或在房屋使用期间未尽约定的修缮义务，经房屋安全鉴定机构书面确认严重影响居住的。乙方有权解除合同。\n\n（二）乙方（或实际居住人）有下列行为之一的，甲方有权解除合同，收回出租房屋，申请对象5年内不得再次申请，并将有关情况记入乙方信用档案，相关规定按照《璧山高新技术产业开发区公共租赁住房管理实施细则》执行：\n\n1、以提供虚假证明材料等方式骗租公共租赁住房的；\n\n2、转租、出借的；\n\n3、改变住房结构或使用性质的；"}]', NULL, NULL, '2026-09-07 01:02:51.273131+00', '2026-09-07 01:02:52.675287+00', '2026-09-07 07:25:10.850614+00', NULL, '', '2', '', '1', '100000519', NULL, '这是一份公共租赁住房租赁合同的第6页（共10页）。主要内容为：

- **第五至七条续文**：规定乙方（承租方）需配合甲方及物业的房屋维护、入户走访、信息采集等工作；甲方设立专项维修资金用于共用部位和设施的维修改造；乙方不得在租赁房屋外墙设置标志、广告或其他凸出物。

- **第八条 合同的解除与终止**：约定甲方房屋不符合安全条件时乙方可解除合同；乙方若有骗租、转租出借、改变住房结构或使用性质等行为，甲方有权解除合同并收回房屋，且5年内不得再次申请，相关情况记入信用档案，按照《璧山高新技术产业开发区公共租赁住房管理实施细则》执行。', '0', 'ready', '', ''),
('59a39324-bec3-4c11-92f4-05d07efb9b0b', '10000', '058fac0b-8cd8-4df8-aa19-8cec300c7113', '5e358dad-c13f-4bba-b295-c1c04d9622fa', '公司地址：重庆市璧山区青杠街道新立路 106
联系电话：023-41556137 传 真：023-41556130 公司网址：http://www.cdxdty.com
重庆星达铜业有限公司
星达行政字〔2026〕11 号 签发人：廖宏
关于对汪艳、王郑红违规行为及质管部手机管理问题
的处罚通报
公司各部门、全体员工：
近期，行政部核查发现，仓库、质管部多名员工存在工作失职、
违反劳动纪律行为，同时查实质管部手机管理存在漏洞，导致员工违
规怠工、质量管控失严。为严肃纪律、压实岗位职责、杜绝同类问题
复发，现将违规事实、处罚决定及整改要求通报如下：
一、相关违规事实及处罚决定
（一）仓库主管汪艳工作失职、屡犯操作失误问题
1. 历史违规记录
依据《星达行政字〔2026〕05 号》通报，汪艳于 2026 年 3 月 16
日因 ERP 配货操作失误，造成单实不符，已被公司处罚。
2. 本次违规事实
2026 年 7 月 1 日，距前次处罚仅 3 个月，汪艳再次出现工作失误。
其在开具客户销售计量单时，将 TYφ3.0 电工圆铜线实际重量
1847.5kg 误填为 1874.5kg，误差 27kg，造成计量单实重量不符。本
次经驾驶员及时核对未造成经济损失，但属于重复违规。

公司地址：重庆市璧山区青杠街道新立路 106
联系电话：023-41556137 传 真：023-41556130 公司网址：http://www.cdxdty.com
3. 风险提示
单据开具、重量核对为物资流转关键环节，长期工作疏忽极易引
发货物短缺、客户索赔等经营风险，严重损害公司利益。
4. 处罚依据及决定
依据《AD-018 奖惩制度》相关规定，结合其重复违规、整改不力
的情况，予以从重处罚：
（1）给予经济罚款 200 元，从 2026 年 6 月员工工资中扣除；
（2）给予书面警告一次，记入个人人事档案，作为年度考核、评
优、晋升的重要依据。
（二）质管部员工王郑红上班违规违纪问题
2026 年 6 月下旬至 7 月 1 日，行政部监控抽查发现，质管部员工
王郑红夜班期间多次在岗玩手机、睡觉，擅离岗位职责，造成质检缺
位、抽检不达标，是近期质量问题频发的重要原因，严重违反劳动纪
律，具体违规情况如下：
1. 王郑红违规事实
（1）玩手机：6 月 24 日多时段、7 月 1 日多时段持续在岗玩手机；
（2）睡觉：7 月 1 日 05:23-06:02 在岗睡觉，履职缺位。
2. 处罚依据及决定
依据公司《AD-018 奖惩制度》及《质管部绩效考核明细表》相关
规定，王郑红夜班多次违规、影响质量管控，情节严重，予以处罚：
（1）处以经济罚款 300 元（含玩手机、睡觉违规累加），从 2026

公司地址：重庆市璧山区青杠街道新立路 106
联系电话：023-41556137 传 真：023-41556130 公司网址：http://www.cdxdty.com
年 6 月工资中扣除；
（2）给予书面警告一次，记入个人档案，取消年度评优资格。
（三）质管部手机管理问题及专项整改要求
经查，质管部员工手机豁免管理制度执行松散，部分人员滥用手
机使用权限，导致夜班怠工、质检缺位。为补齐管理短板，现明确整
改要求：
1. 严控权限：夜班每班仅限 1 人获批携带手机，仅用于业务沟
通，严禁私用。
2. 严格报备：获准人员每日上岗前必须向主管报备，未报备人
员一律手机入柜管理。
3. 从严追责：行政部重点抽查质管部夜班纪律，后续违规问题
将追责当事人及部门主管。
二、全员纪律重申及工作要求
为规范全员履职、严肃劳动纪律，杜绝同类问题频发，现重
申全员工作要求：
1. 严谨履职、严控差错。数据录入、单据开具、物资核对必
须双人复核，杜绝粗心失误，防范经营风险。
2. 严守纪律、在岗尽责。工作期间严禁睡觉、玩手机、脱岗
等怠工行为，夜班人员强化自律与互相监督。
3. 压实部门管理责任。各部门负责人为纪律管理第一责任人，

公司地址：重庆市璧山区青杠街道新立路 106
联系电话：023-41556137 传 真：023-41556130 公司网址：http://www.cdxdty.com
常态化自查自纠，堵塞管理漏洞。
4. 全员举一反三自查。各部门组织学习本通报，排查岗位风
险、落实防控措施。行政部常态化执纪抽查，严查各类违规行为。
公司重申：对漠视制度、玩忽职守、在岗怠工的行为一律从严处
罚、绝不姑息。全体员工须引以为戒、严守规章、履职尽责，维
护公司正常生产经营秩序。
特此通报。
