这份文件是璧山高新技术产业开发区管理委员会印制的《公共租赁住房租赁合同》，编号为0001-3541。合同出租方为重庆两山建设投资集团有限公司，承租方为重庆星达铜业有限公司。合同依据《民法典》及相关公共租赁住房管理规定签订，租赁房屋为“两山景苑公租房”。合同中详细列出了双方的地址、邮编及联系电话等信息。合同规定了乙方违约情形，包括无正当理由连续空置房屋、拖欠租金、从事违法活动等，若乙方违约，甲方有权解除协议并收取租金及履约保证金。合同还规定了租赁期满、提前退租、居住人不符合申请条件等情况下的处理方式，以及房屋腾退的相关规定。', '4', 't', '0', '0', '', '', 'summary', '7200c5e7-ebb0-48bb-9943-2da2ab9beece', '', NULL, NULL, '2026-09-07 01:02:55.447372+00', '2026-09-07 01:02:55.447372+00', '2026-09-07 07:25:10.850614+00', NULL, '', '0', '', '1', '100000522', NULL, '# Summary
这份文件是璧山高新技术产业开发区管理委员会印制的《公共租赁住房租赁合同》，编号为0001-3541。合同出租方为重庆两山建设投资集团有限公司，承租方为重庆星达铜业有限公司。合同依据《民法典》及相关公共租赁住房管理规定签订，租赁房屋为“两山景苑公租房”。合同中详细列出了双方的地址、邮编及联系电话等信息。合同规定了乙方违约情形，包括无正当理由连续空置房屋、拖欠租金、从事违法活动等，若乙方违约，甲方有权解除协议并收取租金及履约保证金。合同还规定了租赁期满、提前退租、居住人不符合申请条件等情况下的处理方式，以及房屋腾退的相关规定。', '0', 'ready', '', ''),
('62cd1397-5193-4c4a-852c-98226a181024', '10000', '058fac0b-8cd8-4df8-aa19-8cec300c7113', '5e358dad-c13f-4bba-b295-c1c04d9622fa', '（三）质管部手机管理问题及专项整改要求
经查，质管部员工手机豁免管理制度执行松散，部分人员滥用手
机使用权限，导致夜班怠工、质检缺位。为补齐管理短板，现明确整
改要求：
1. 严控权限：夜班每班仅限 1 人获批携带手机，仅用于业务沟
通，严禁私用。
2. 严格报备：获准人员每日上岗前必须向主管报备，未报备人
员一律手机入柜管理。
3. 从严追责：行政部重点抽查质管部夜班纪律，后续违规问题
将追责当事人及部门主管。
二、全员纪律重申及工作要求
为规范全员履职、严肃劳动纪律，杜绝同类问题频发，现重
申全员工作要求：
1. 严谨履职、严控差错。数据录入、单据开具、物资核对必
须双人复核，杜绝粗心失误，防范经营风险。
2. 严守纪律、在岗尽责。工作期间严禁睡觉、玩手机、脱岗
等怠工行为，夜班人员强化自律与互相监督。
