('8b594af8-02e9-40ba-a775-9e7158f4f500', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '8022871a-b137-47c6-a95b-a7aa0835c71b', '这是一份检测服务合同的第二页（共4页），以表格形式列出了合同双方的权利义务，主要包括以下内容：

- **乙方责任和义务**：乙方须按合同提供检测服务、采用国家规定的检验方法和标准、对检测数据保密、仅对送检样品负责、保证廉洁检测等。
- **保密条款**：双方互相承担保密义务，未经书面许可不得向第三方泄露合作范围、内容、费用等，泄密方须承担经济和法律责任。
- **违约责任**：规定了因甲方原因无法采样时的费用承担、付款延迟的滞纳金（每日0.1%，上限20%）、单方解约须支付20%违约金、违反保密条款支付10%违约金等。
- **免责条款**：因不可抗力（自然灾害、战争、罢工、疫情等）或甲方原因导致乙方无法履约时，乙方不承担责任。

页面右下角盖有银行印章，表明该文件已加盖了公章确认。', '0', 't', '0', '0', '', '', 'image_caption', 'e523e9ef-ff14-463d-89b7-a1afc5c19a5a', '[{"url":"resource://j439k0aKphSBBMCfUCqXtA","original_url":"resource://j439k0aKphSBBMCfUCqXtA","start_pos":0,"end_pos":0,"caption":"这是一份检测服务合同的第二页（共4页），以表格形式列出了合同双方的权利义务，主要包括以下内容：\n\n- **乙方责任和义务**：乙方须按合同提供检测服务、采用国家规定的检验方法和标准、对检测数据保密、仅对送检样品负责、保证廉洁检测等。\n- **保密条款**：双方互相承担保密义务，未经书面许可不得向第三方泄露合作范围、内容、费用等，泄密方须承担经济和法律责任。\n- **违约责任**：规定了因甲方原因无法采样时的费用承担、付款延迟的滞纳金（每日0.1%，上限20%）、单方解约须支付20%违约金、违反保密条款支付10%违约金等。\n- **免责条款**：因不可抗力（自然灾害、战争、罢工、疫情等）或甲方原因导致乙方无法履约时，乙方不承担责任。\n\n页面右下角盖有银行印章，表明该文件已加盖了公章确认。","ocr_text":"| | |\n|---|---|\n| | 4.采样平台必须保证安全、牢固，否则乙方不予采样，且一切发生费用由甲方负责。\u003cbr\u003e5.按本协议约定及时向乙方支付检测费用。\u003cbr\u003e6.检测报告未经乙方同意不得擅自修改，不得提供或转让给第三方使用。 |\n| 乙方责任和义务 | 1.按照合同约定提供检测服务，为甲方出具检测报告。\u003cbr\u003e2.采用合适谨慎态度及科学准确的方法，以保证提供优质、高效、准确、快速的检测服务。\u003cbr\u003e3.乙方应采用国家规定的检验方法和标准，在双方协商一致的时间内完成分析测试任务并出具检测报告给甲方。\u003cbr\u003e4.乙方必须对一切检测数据和检验结果保密，除法律规定外，未经甲方书面同意不得泄露给任何第三方。\u003cbr\u003e5.乙方出具的检测报告，仅对被送检样品和现场采取的样品负责。在任何情况下，乙方的责任不能超出乙方对样品作出的检测报告的范围。检测结果的使用、使用所产生的直接或间接损失，乙方不承担任何责任。\u003cbr\u003e6.承诺现场采样人员在采样过程中严禁以任何形式索取好处费或其他与客户约定之外的行为，保证廉洁检测。 |\n| 保密条款 | 1.甲方应为乙方所提供的技术情报和资料及非正式出版物等承担保密义务。\u003cbr\u003e2.乙方应为甲方所提供的资料、环境状况、产品技术、生产工艺等承担保密义务。\u003cbr\u003e3.未经对方书面许可，任何一方不得向第三方泄露本合同的如下内容：合作范围、内容、方式、费用；双方权利、责任；争议处理的方式等等。\u003cbr\u003e4.一旦一方泄密，则泄密方必须承担相应的经济和法律责任。 |\n| 违约责任 | 1.因甲方原因（受检单位监测条件不能达到要求）导致乙方检测人员到达现场后无法进行采样或不能一次性完成的（即超出天数），乙方不承担责任；且甲方需额外向乙方支付人工及车辆费用（人工费用按每人每天 500 元计算，不足 1 天按 1 天计；车辆费用按每车每公里 2 元计）；\u003cbr\u003e2.现场检测人员仅对本协议委托项目进行采样。如遇现场实际情况与协议不符或需更改协议，需另外以书面方式写明更改要求，并由甲方代表人签字或单位盖章，检测工作完成时间自甲方盖章生效之日起重新计算；\u003cbr\u003e3.甲方若因付款不及时或未按照要求付款，导致报告延期的，所产生的一切责任和后果甲方自己承担，与乙方无关；\u003cbr\u003e4.若不是乙方原因而甲方未能按本合同约定付款，甲方应按下列比例向乙方支付滞纳金：每迟一日，甲方向乙方支付该笔延付款的 0.1%违约金，付款日期以甲方银行承付日期为准，迟付款违约金总金额不超过合同总金额的 20%；\u003cbr\u003e5.甲乙双方若无正当理由要求解除协议的，违约方应当向守约方支付协议总价的 20%作为违约金；\u003cbr\u003e6.若此项目需要复测，要收取复测费用，复测费用双方协商，并签订补充协议；\u003cbr\u003e7.一方违反保密条款导致协议另一方遭受损失或不利影响的，应按协议总价款的 10%支付违约金。 |\n| 免责条款 | 检测服务的顺利进行，依靠甲乙双方的共同努力和彼此配合。因在乙方控制范围之外的原因造成乙方无法履行合同条款时，乙方不承担相关责任，情况包括但不限于以下：\u003cbr\u003e1. 发生不可抗力时，任何一方对于由以下不可抗力造成的违约均不负有法律责任：政府的法律法规；\u003cbr\u003e2. 自然灾害，包括但不限于洪水、旱灾、台风、地震、火灾、疫情等；\u003cbr\u003e3. 罢工或暴乱；\u003cbr\u003e4. 战争或军事行为或国际制裁；\u003cbr\u003e5. 甲方人员不按照本合同条款履行责任时，如资料或样品不能按照乙方要求提供时；\u003cbr\u003e6. 由于甲方原因致使乙方未能按合同规定完成检测服务而造成甲方蒙受任何损失或损害时； |"}]', NULL, NULL, '2026-09-07 01:18:43.995892+00', '2026-09-07 01:18:45.77302+00', '2026-09-07 01:18:58.027072+00', NULL, '', '2', '', '1', '100000533', NULL, '这是一份检测服务合同的第二页（共4页），以表格形式列出了合同双方的权利义务，主要包括以下内容：

- **乙方责任和义务**：乙方须按合同提供检测服务、采用国家规定的检验方法和标准、对检测数据保密、仅对送检样品负责、保证廉洁检测等。
- **保密条款**：双方互相承担保密义务，未经书面许可不得向第三方泄露合作范围、内容、费用等，泄密方须承担经济和法律责任。
- **违约责任**：规定了因甲方原因无法采样时的费用承担、付款延迟的滞纳金（每日0.1%，上限20%）、单方解约须支付20%违约金、违反保密条款支付10%违约金等。
- **免责条款**：因不可抗力（自然灾害、战争、罢工、疫情等）或甲方原因导致乙方无法履约时，乙方不承担责任。

页面右下角盖有银行印章，表明该文件已加盖了公章确认。', '0', 'ready', '', ''),
('173edb96-8936-4930-976d-f88f3e7ed5d0', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '8022871a-b137-47c6-a95b-a7aa0835c71b', '# Summary
这是一份关于重庆星达铜业有限公司年度污染物自行监测检测的合同附件。合同中包含了详细的检测信息，包括项目地址、联系人、检测类别、检测因子、检测点位、检测天数和检测频次等。项目地址位于重庆市璧山区青杠街道新立路106号，项目联系人为寇江。检测内容包括生活污水排放口的pH值、悬浮物、化学需氧量、氨氮、总磷、石油类等因子，每年检测1次，频次为3次；厂界噪声检测每季度1次，昼、夜各一次。文件上盖有红色公章，为合同共4页中的第4页。', '1', 't', '0', '0', '', '', 'summary', 'e523e9ef-ff14-463d-89b7-a1afc5c19a5a', '', NULL, NULL, '2026-09-07 01:18:52.38279+00', '2026-09-07 01:18:52.38279+00', '2026-09-07 01:18:58.027072+00', NULL, '', '0', '', '1', '100000534', NULL, '# Summary
这是一份关于重庆星达铜业有限公司年度污染物自行监测检测的合同附件。合同中包含了详细的检测信息，包括项目地址、联系人、检测类别、检测因子、检测点位、检测天数和检测频次等。项目地址位于重庆市璧山区青杠街道新立路106号，项目联系人为寇江。检测内容包括生活污水排放口的pH值、悬浮物、化学需氧量、氨氮、总磷、石油类等因子，每年检测1次，频次为3次；厂界噪声检测每季度1次，昼、夜各一次。文件上盖有红色公章，为合同共4页中的第4页。', '0', 'ready', '', ''),
('ca084d2d-47fe-4e02-80b2-099499d48554', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '8022871a-b137-47c6-a95b-a7aa0835c71b', '| | 7. 甲方单方原因更改乙方出具的检测报告，或对乙方出具的检测报告进行取舍，由此造成损失或纠纷时；<br>8. 甲方由于其提供的样品、技术文件存在知识产权问题，由此造成损失或纠纷时。 |
|:---|:---|
| 其他 | 1. 乙方不作检测数据必达标的承诺，若检测数据不达标，则需甲方整改后复测；并需签订补充协议，报告时限顺延。<br>2. 乙方的报告如未加盖 CMA 章和检验检测专用章无效，涂改无效，复印无效。未经乙方同意，不得复制报告。经同意复制的报告必须全文复制，如未重新加盖乙方检验检测专用章，则该复制件无效。<br>3. 未加盖 CMA 章的检测报告仅供甲方内部使用，不具有向社会出示公正性的作用。<br>4. 在协议执行过程中，本协议附件与本协议具有同等效力。<br>5. 如有未尽事宜，经双方协商可签订补充协议，补充协议与本协议具有同等法律效力。<br>6. 本协议一式贰份，经双方签字盖章后生效，甲、乙双方各持壹份；扫描件、复印件具有同等法律效力。<br>7. 在履行本合同过程中发生争议时，双方应尽友好协商解决；如协商未能解决，则直接向重庆市渝北区人民法院起诉。 |

甲方：重庆星达铜业有限公司　　　　　　　　乙方：重庆大安检测技术有限公司

委托代理人：（手写签名）　　　　　　　　　委托代理人：（手写签名）

地址：（手写，部分被印章遮挡）重庆市渝北区……路106号　　　　　　地址：重庆市渝北区食品城大道 18 号重庆广告产业园区 12-1-6-1、12-1-6-2

电话：（手写）18996912075　　　　　　　　电话：17830549433

开户银行：　　　　　　　　　　　　　　　　开户银行：中国民生银行股份有限公司重庆两江新区支行

