('3ebeb94e-9f5d-4fc1-91d5-af339ecdb695', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '8022871a-b137-47c6-a95b-a7aa0835c71b', '# 环境检测委托合同

甲方（委托方）：重庆星达铜业有限公司

乙方（受托方）：重庆大安检测技术有限公司

渝大安（环）检合同[　　　]第　　　号

| 项目 | 内容 |
| --- | --- |
| 前言 | 为更好的给甲方提供完整的高品质服务，便于双方合作的顺利进行，根据《中华人民共和国民法典》及有关法律法规，本着平等互利的原则，通过友好协商，双方同意签订以下协议。 |
| 甲方（委托方）——单位名称 | 重庆星达铜业有限公司 |
| 甲方（委托方）——联系人 | 寇江 |
| 甲方（委托方）——联系电话 | 18996912075 |
| 乙方（受托方）——单位名称 | 重庆大安检测技术有限公司 |
| 乙方（受托方）——联系人 | 秦银节 |
| 乙方（受托方）——联系电话 | 17830549433 |
| 乙方（受托方）——检测方案 | ☑由甲方提供，检测方案详见：附件 1 |
| 乙方（受托方）——是否具备现场检测条件 | 现场检测条件要求详见：在保证满足正常现场检测条件后，乙方方可安排采样 |
| 乙方（受托方）——是否分包 | □是　☑否 |
| 检测费用及支付方式 | 1. 检测费用￥ 6800 元 □加急费用￥ ／ 元（按检测费用的%收取），总计：￥ 6800 元，（人民币大写：陆仟捌佰元整）。2. 双方合同签订后乙方开具全额增值税发票，甲方在收到发票后 3 个工作日内一次性付清检测费用￥ 6800 元。 |
| 收费依据 | 按甲乙双方协商收费。 |
| 甲方所需发票类型 | □增值税普通发票　☑增值税专用发票　执行税率：6% |
| 完成期限 | 合同生效后 7 个工作日内安排检测，每次检测之后 15 个工作日内提交检测报告，乙方向甲方提交 2 份报告。由于甲方项目原因造成技术服务工作不能按期完成，乙方可延期交付检测报告，具体交付日期双方另行议定。 |
| 报告数量和领取方式 | 乙方向甲方提交报告，若超过 2 份，则检测报告超过部分按每本收取 50 元工本费。报告其他要求：报告领取方式：□电子文件发送；☑快递发送；□联系人自取。 |
| 其他约定 | ／ |
| 甲方责任和义务 | 1. 甲方对协议约定项目所提供的检测所需的相关信息和资料的真实性、完整性、合法性、有效性承担法律责任；2. 提供一切必要的设备及资料以保证乙方采样的顺利进行。3. 在实施采样前，甲方应明确告知乙方采样人员有关的规章制度，并采取一切必要的措施，以确保乙方在检测、采样的服务过程中的工作条件、场地和装置的安全，并安排一名熟悉委托方情况的人员配合乙方进行现场采样。因甲方原因，致使乙方采样人员人身安全受到伤害时，甲方应承担相应责任和经济赔偿。 |', '0', 't', '0', '0', '', '', 'image_ocr', 'e523e9ef-ff14-463d-89b7-a1afc5c19a5a', '[{"url":"resource://B2reOy39AJndLtXrvi45Sw","original_url":"resource://B2reOy39AJndLtXrvi45Sw","start_pos":0,"end_pos":0,"caption":"这是一份**环境检测委托合同**（第1页，共4页）。主要内容包括：\n\n- **甲方（委托方）**：重庆星达铜业有限公司，联系人为寇江\n- **乙方（受托方）**：重庆大安检测技术有限公司，联系人为秦银节\n- **检测费用**：人民币6800元（陆仟捌佰元整），合同签订后乙方开具全额增值税专用发票（税率6%），甲方收到发票后3个工作日内一次性付清\n- **完成期限**：合同生效后7个工作日内安排检测，每次检测后15个工作日内提交检测报告\n- **报告交付**：乙方向甲方提交2份报告，通过快递发送\n- 其他条款包括收费依据、甲方责任和义务等\n\n文件右上角和右侧盖有红色合同骑缝章。","ocr_text":"# 环境检测委托合同\n\n甲方（委托方）：重庆星达铜业有限公司\n\n乙方（受托方）：重庆大安检测技术有限公司\n\n渝大安（环）检合同[　　　]第　　　号\n\n| 项目 | 内容 |\n| --- | --- |\n| 前言 | 为更好的给甲方提供完整的高品质服务，便于双方合作的顺利进行，根据《中华人民共和国民法典》及有关法律法规，本着平等互利的原则，通过友好协商，双方同意签订以下协议。 |\n| 甲方（委托方）——单位名称 | 重庆星达铜业有限公司 |\n| 甲方（委托方）——联系人 | 寇江 |\n| 甲方（委托方）——联系电话 | 18996912075 |\n| 乙方（受托方）——单位名称 | 重庆大安检测技术有限公司 |\n| 乙方（受托方）——联系人 | 秦银节 |\n| 乙方（受托方）——联系电话 | 17830549433 |\n| 乙方（受托方）——检测方案 | ☑由甲方提供，检测方案详见：附件 1 |\n| 乙方（受托方）——是否具备现场检测条件 | 现场检测条件要求详见：在保证满足正常现场检测条件后，乙方方可安排采样 |\n| 乙方（受托方）——是否分包 | □是　☑否 |\n| 检测费用及支付方式 | 1. 检测费用￥ 6800 元 □加急费用￥ ／ 元（按检测费用的%收取），总计：￥ 6800 元，（人民币大写：陆仟捌佰元整）。2. 双方合同签订后乙方开具全额增值税发票，甲方在收到发票后 3 个工作日内一次性付清检测费用￥ 6800 元。 |\n| 收费依据 | 按甲乙双方协商收费。 |\n| 甲方所需发票类型 | □增值税普通发票　☑增值税专用发票　执行税率：6% |\n| 完成期限 | 合同生效后 7 个工作日内安排检测，每次检测之后 15 个工作日内提交检测报告，乙方向甲方提交 2 份报告。由于甲方项目原因造成技术服务工作不能按期完成，乙方可延期交付检测报告，具体交付日期双方另行议定。 |\n| 报告数量和领取方式 | 乙方向甲方提交报告，若超过 2 份，则检测报告超过部分按每本收取 50 元工本费。报告其他要求：报告领取方式：□电子文件发送；☑快递发送；□联系人自取。 |\n| 其他约定 | ／ |\n| 甲方责任和义务 | 1. 甲方对协议约定项目所提供的检测所需的相关信息和资料的真实性、完整性、合法性、有效性承担法律责任；2. 提供一切必要的设备及资料以保证乙方采样的顺利进行。3. 在实施采样前，甲方应明确告知乙方采样人员有关的规章制度，并采取一切必要的措施，以确保乙方在检测、采样的服务过程中的工作条件、场地和装置的安全，并安排一名熟悉委托方情况的人员配合乙方进行现场采样。因甲方原因，致使乙方采样人员人身安全受到伤害时，甲方应承担相应责任和经济赔偿。 |"}]', NULL, NULL, '2026-09-07 01:19:26.3704+00', '2026-09-07 01:19:27.393865+00', NULL, NULL, '', '2', '', '1', '100000537', NULL, '# 环境检测委托合同

甲方（委托方）：重庆星达铜业有限公司

乙方（受托方）：重庆大安检测技术有限公司

渝大安（环）检合同[　　　]第　　　号

| 项目 | 内容 |
| --- | --- |
| 前言 | 为更好的给甲方提供完整的高品质服务，便于双方合作的顺利进行，根据《中华人民共和国民法典》及有关法律法规，本着平等互利的原则，通过友好协商，双方同意签订以下协议。 |
| 甲方（委托方）——单位名称 | 重庆星达铜业有限公司 |
| 甲方（委托方）——联系人 | 寇江 |
| 甲方（委托方）——联系电话 | 18996912075 |
| 乙方（受托方）——单位名称 | 重庆大安检测技术有限公司 |
| 乙方（受托方）——联系人 | 秦银节 |
| 乙方（受托方）——联系电话 | 17830549433 |
| 乙方（受托方）——检测方案 | ☑由甲方提供，检测方案详见：附件 1 |
| 乙方（受托方）——是否具备现场检测条件 | 现场检测条件要求详见：在保证满足正常现场检测条件后，乙方方可安排采样 |
| 乙方（受托方）——是否分包 | □是　☑否 |
| 检测费用及支付方式 | 1. 检测费用￥ 6800 元 □加急费用￥ ／ 元（按检测费用的%收取），总计：￥ 6800 元，（人民币大写：陆仟捌佰元整）。2. 双方合同签订后乙方开具全额增值税发票，甲方在收到发票后 3 个工作日内一次性付清检测费用￥ 6800 元。 |
| 收费依据 | 按甲乙双方协商收费。 |
| 甲方所需发票类型 | □增值税普通发票　☑增值税专用发票　执行税率：6% |
| 完成期限 | 合同生效后 7 个工作日内安排检测，每次检测之后 15 个工作日内提交检测报告，乙方向甲方提交 2 份报告。由于甲方项目原因造成技术服务工作不能按期完成，乙方可延期交付检测报告，具体交付日期双方另行议定。 |
| 报告数量和领取方式 | 乙方向甲方提交报告，若超过 2 份，则检测报告超过部分按每本收取 50 元工本费。报告其他要求：报告领取方式：□电子文件发送；☑快递发送；□联系人自取。 |
| 其他约定 | ／ |
| 甲方责任和义务 | 1. 甲方对协议约定项目所提供的检测所需的相关信息和资料的真实性、完整性、合法性、有效性承担法律责任；2. 提供一切必要的设备及资料以保证乙方采样的顺利进行。3. 在实施采样前，甲方应明确告知乙方采样人员有关的规章制度，并采取一切必要的措施，以确保乙方在检测、采样的服务过程中的工作条件、场地和装置的安全，并安排一名熟悉委托方情况的人员配合乙方进行现场采样。因甲方原因，致使乙方采样人员人身安全受到伤害时，甲方应承担相应责任和经济赔偿。 |', '0', 'ready', '', ''),
