('2ce8f222-6aa3-4c10-b63a-53429a03b0cf', '10000', '0049ce9e-f051-420b-b226-178096f9c72f', '74f5976c-4849-4dfe-a213-b839dcbb90cf', '材料进行清场场或更换，如甲方材料不符合强制性规范要求导致的工程质量事故，应由甲方承担所有 责任及乙方损失。

2、乙方＿＿＿＿＿√＿＿＿＿＿，材料须满足甲方驱验收要求，如乙方材料不符合强制性规范要求导致的工程质量事故，应由乙方承担所有 责任及甲方损失。

**四、施工环境要求**

1、要求甲方地面干燥达到乙方施工条件。

2、施工前甲方应清除地面垃圾及货物，不影响乙方的正常施工。

3、甲方应无偿为乙方提供施工期间的水电，污水处理处不得超过 100 米及临时住所，保证工人的基本生活，施工期间不安排及其他工程队交叉作业。

**备注：** 以上条件不具备导致的地面发白等质量问题，乙方不承担任何责任

**五、特别声明**

1、乙方进场固化剂施工 3 个工作日内一定要做出 50 平米左右成品样品，甲方应在乙方进场的第四个工作日主动来施工现场确认验收。如甲方没有书面提出整改或要求停工等，也没有提出任何异议，乙方视为合格并可大批量生产施工，而后甲方不得以任何理由提出任何质量异议。（备注：如有异议必须书面形式并签名盖章生效）。

2、原基础地面有损坏或地面本身有瑕疵，（如裂纹 沙眼 坑洼） 所导致固化后地面效果不一致的与乙方质量无关。

**六、违约责任**

1、甲方应为乙方的施工提供协调、配合，如由于甲方的责任所造成的延误工期及乙方产生的误工费和地坪质量问题均由甲方负责。

2、乙方应保证工期及严格按照施工工艺施工，如出现质量问题等由乙方负责。

3、甲方应按照合同按时兑现合同商定的付款方式付款，如甲方不及时付款， 乙方有权停工或解除合同，因此所造成的损失由甲方负责。

4、如由于甲方的原因造成交付使用前的损坏由甲方承担，由于乙方的原因造成交付前的损坏由乙方承担。', '0', 't', '0', '0', '', '', 'image_ocr', '6c03e87a-5746-411f-a637-6c1b6b37a131', '[{"url":"resource://U8OUvwyAgCkww34NxahxtQ","original_url":"resource://U8OUvwyAgCkww34NxahxtQ","start_pos":0,"end_pos":0,"caption":"这是一份中文施工合同文件的某一页，主要内容包括：\n\n- **材料责任条款**：规定甲、乙双方材料如不符合强制性规范要求导致工程质量事故时的责任划分；\n- **四、施工环境要求**：要求甲方地面干燥、清除垃圾货物、无偿提供水电及临时住所等施工条件；\n- **备注**：条件不具备导致的地面发白等质量问题乙方不承担责任；\n- **五、特别声明**：约定乙方进场后需在3个工作日内做出约50平米成品样品，由甲方验收确认，以及原基础地面瑕疵不影响乙方质量责任；\n- **六、违约责任**：明确双方在工期延误、质量问题、付款、交付损坏等方面的责任承担。\n\n页面右侧盖有红色印章（部分可见），文中有一处手写勾选标记。","ocr_text":"材料进行清场场或更换，如甲方材料不符合强制性规范要求导致的工程质量事故，应由甲方承担所有 责任及乙方损失。\n\n2、乙方＿＿＿＿＿√＿＿＿＿＿，材料须满足甲方驱验收要求，如乙方材料不符合强制性规范要求导致的工程质量事故，应由乙方承担所有 责任及甲方损失。\n\n**四、施工环境要求**\n\n1、要求甲方地面干燥达到乙方施工条件。\n\n2、施工前甲方应清除地面垃圾及货物，不影响乙方的正常施工。\n\n3、甲方应无偿为乙方提供施工期间的水电，污水处理处不得超过 100 米及临时住所，保证工人的基本生活，施工期间不安排及其他工程队交叉作业。\n\n**备注：** 以上条件不具备导致的地面发白等质量问题，乙方不承担任何责任\n\n**五、特别声明**\n\n1、乙方进场固化剂施工 3 个工作日内一定要做出 50 平米左右成品样品，甲方应在乙方进场的第四个工作日主动来施工现场确认验收。如甲方没有书面提出整改或要求停工等，也没有提出任何异议，乙方视为合格并可大批量生产施工，而后甲方不得以任何理由提出任何质量异议。（备注：如有异议必须书面形式并签名盖章生效）。\n\n2、原基础地面有损坏或地面本身有瑕疵，（如裂纹 沙眼 坑洼） 所导致固化后地面效果不一致的与乙方质量无关。\n\n**六、违约责任**\n\n1、甲方应为乙方的施工提供协调、配合，如由于甲方的责任所造成的延误工期及乙方产生的误工费和地坪质量问题均由甲方负责。\n\n2、乙方应保证工期及严格按照施工工艺施工，如出现质量问题等由乙方负责。\n\n3、甲方应按照合同按时兑现合同商定的付款方式付款，如甲方不及时付款， 乙方有权停工或解除合同，因此所造成的损失由甲方负责。\n\n4、如由于甲方的原因造成交付使用前的损坏由甲方承担，由于乙方的原因造成交付前的损坏由乙方承担。"}]', NULL, NULL, '2026-09-07 05:10:14.679137+00', '2026-09-07 05:10:14.679137+00', '2026-09-07 05:10:15.267834+00', NULL, '', '0', '', '1', '100000672', NULL, '材料进行清场场或更换，如甲方材料不符合强制性规范要求导致的工程质量事故，应由甲方承担所有 责任及乙方损失。

